import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { expect, it } from "vitest";

// The CLI (npm run api:generate) prepends this banner to the output of the programmatic API.
const BANNER =
  "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n";

it("schema.d.ts matches the committed OpenAPI contract", async () => {
  const contract = pathToFileURL(
    resolve(import.meta.dirname, "../../../specs/001-kanban-ticketing/contracts/openapi.json"),
  );
  const committed = readFileSync(resolve(import.meta.dirname, "schema.d.ts"), "utf8");
  const generated = BANNER + astToString(await openapiTS(contract));
  expect(committed === generated, 'API types are out of date: run "npm run api:generate"').toBe(
    true,
  );
});
